use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let array = input.as_array().expect("Input must be an array");
    let mut total_cents = 0;

    for item in array {
        let item_array = item.as_array().expect("Each item must be an array");
        let unit_price_cents = item_array[0].as_i64().expect("Unit price must be an integer");
        let quantity = item_array[1].as_i64().expect("Quantity must be an integer");

        total_cents += unit_price_cents * quantity;
    }

    Value::Number(serde_json::Number::from(total_cents))
}
